inputs = ['cy', 'uwak', 'ikcix', 'bb', 'zwwai']
outputs = ['uuy', 'uwax', 'ixuuie', 'vhvh', 'cuuwwai']

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Simple approach: find first position where they differ
    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion
    if len(s_in) < len(s_out):
        # Insertion case
        for i in range(min_len):
            if s_in[i] != s_out[i]:
                return (s_in[i:], s_out[i:], i)
        return (s_in[min_len:], s_out[min_len:], min_len)
    elif len(s_in) > len(s_out):
        # Deletion case
        for i in range(min_len):
            if s_in[i] != s_out[i]:
                return (s_in[i:], s_out[i:], i)
        return (s_in[min_len:], s_out[min_len:], min_len)
    else:
        # Same length - find first difference
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
        return (None, None, -1)

print("Detailed edit analysis:")
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        old_sub, new_sub, pos = find_minimal_edit(inputs[i], outputs[i])
        print(f"'{inputs[i]}' -> '{outputs[i]}': change '{old_sub}' to '{new_sub}' at position {pos}")

